s = input().strip()

# count_a: 累计字符 a 出现的次数
# count_ab: 累计可以组成子序列 "ab" 的种数
# count_abc: 累计可以组成子序列 "abc" 的种数
count_a = 0
count_ab = 0
count_abc = 0

# 遍历日志中的每条记录
for ch in s:
    if ch == 'a':
        # 遇到 a，增加 a 的计数
        count_a += 1
    elif ch == 'b':
        # 遇到 b，可与之前所有的 a 组合成 "ab"
        count_ab += count_a
    elif ch == 'c':
        # 遇到 c，可与之前所有的 "ab" 组合成 "abc"
        count_abc += count_ab
    # d 字符不影响计数，直接跳过

# 输出最终能够抽出 "abc" 的方式总数
print(count_abc)
```

